(()=>{const init=()=>{const input=document.getElementById("reference"),drop=document.getElementById("referenceDrop"),box=document.getElementById("previewRef"),status=document.getElementById("pasteStatus");if(!input||!drop||!box||!status)return;let currentFile=null,objectUrl=null;const show=f=>{if(!f)return;if(!f.type||!f.type.startsWith("image/")){status.textContent="O item copiado não é uma imagem. Use JPG, PNG ou WEBP.";return;}if(f.size>5*1024*1024){status.textContent="A imagem deve ter até 5 MB.";return;}currentFile=f;window.__uvcReferenceFile=f;try{const dt=new DataTransfer();dt.items.add(f);input.files=dt.files;}catch(_){}if(objectUrl)URL.revokeObjectURL(objectUrl);objectUrl=URL.createObjectURL(f);box.hidden=false;box.removeAttribute("hidden");box.style.cssText="display:block!important;visibility:visible!important;min-height:70px;margin:12px 0;padding:12px;border:1px solid #8b7dbd66;border-radius:12px;background:#080711";box.replaceChildren();const head=document.createElement("div");head.style.cssText="display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:10px";const label=document.createElement("div");label.textContent="✓ Prévia da foto de referência";label.style.cssText="color:#c7a8ff;font-size:14px";const remove=document.createElement("button");remove.type="button";remove.textContent="✕";remove.title="Remover foto e escolher outra";remove.setAttribute("aria-label","Remover foto de referência");remove.style.cssText="display:inline-flex;align-items:center;justify-content:center;min-width:34px;min-height:34px;border:1px solid #8e7bbd88;border-radius:8px;background:#171127;color:#fff;font-size:18px;cursor:pointer";remove.addEventListener("click",()=>{currentFile=null;window.__uvcReferenceFile=null;input.value="";if(objectUrl){URL.revokeObjectURL(objectUrl);objectUrl=null;}box.replaceChildren();box.hidden=true;box.style.display="none";status.textContent="Foto removida. Selecione ou cole outra imagem.";});head.append(label,remove);const img=document.createElement("img");img.src=objectUrl;img.alt="Prévia da foto selecionada";img.style.cssText="display:block!important;visibility:visible!important;width:auto;max-width:100%;max-height:260px;object-fit:contain;margin:0 auto;border-radius:10px";img.onerror=()=>{status.textContent="O navegador não conseguiu exibir essa imagem. Tente salvar em JPG ou PNG.";};box.append(head,img);status.textContent="Foto pronta para gerar: "+(f.name||"imagem colada");};input.addEventListener("change",()=>show(input.files&&input.files[0]),true);input.addEventListener("input",()=>show(input.files&&input.files[0]),true);drop.addEventListener("dragover",e=>{e.preventDefault();});drop.addEventListener("drop",e=>{e.preventDefault();const f=e.dataTransfer&&Array.from(e.dataTransfer.files||[]).find(x=>x.type&&x.type.startsWith("image/"));if(f)show(f);});const paste=async e=>{const c=e.clipboardData;if(!c)return;let f=null;for(const item of Array.from(c.items||[])){if(item.type&&item.type.startsWith("image/")){f=item.getAsFile();if(f)break;}}if(!f&&c.files&&c.files.length)f=Array.from(c.files).find(x=>x.type&&x.type.startsWith("image/"));if(f){e.preventDefault();e.stopImmediatePropagation();show(f);return;}const raw=(c.getData("text/plain")||c.getData("text/uri-list")||"").trim();let u;try{u=new URL(raw);}catch{return;}const host=u.hostname.toLowerCase();if(!(host==="pinterest.com"||host.endsWith(".pinterest.com")||host==="pin.it"||host.endsWith(".pin.it")||host==="i.pinimg.com"))return;e.preventDefault();e.stopImmediatePropagation();status.textContent="Importando imagem do Pinterest…";try{const r=await fetch("/api/influencers/reference-from-url",{method:"POST",credentials:"same-origin",headers:{"content-type":"application/json"},body:JSON.stringify({url:u.href})});if(!r.ok){let d={};try{d=await r.json();}catch{}throw new Error(d.message||"Não foi possível importar esse link.");}const blob=await r.blob();const type=blob.type||"image/jpeg";show(new File([blob],"referencia-pinterest."+(type==="image/png"?"png":type==="image/webp"?"webp":"jpg"),{type,lastModified:Date.now()}));}catch(err){status.textContent=(err&&err.message)||"Não consegui importar o link. Salve a foto do Pinterest e selecione o arquivo.";}};document.addEventListener("paste",paste,true);drop.addEventListener("paste",paste,true);};if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",init,{once:true});else init();})();
