const importPinterestUrl=async raw=>{let url;try{url=new URL(raw.trim());}catch{return false;}if(!/(^|\\.)pinterest\\.com$/i.test(url.hostname)&&!/(^|\\.)pin\\.it$/i.test(url.hostname)&&url.hostname.toLowerCase()!=="i.pinimg.com")return false;status.textContent="Importando a foto do Pinterest…";try{const response=await fetch("/api/influencers/reference-from-url",{method:"POST",headers:{"content-type":"application/json"},credentials:"same-origin",cache:"no-store",body:JSON.stringify({url:url.href})});if(!response.ok){let data={};try{data=await response.json();}catch{}throw new Error(data.message||"Não consegui importar essa foto do Pinterest.");}const blob=await response.blob();const type=(blob.type||response.headers.get("content-type")||"image/jpeg").split(";")[0];const ext=type==="image/png"?"png":type==="image/webp"?"webp":"jpg";const f=new File([blob],"pinterest-reference."+ext,{type,lastModified:Date.now()});syncInput(f);return true;}catch(err){status.textContent=String(err&&err.message||"Falha ao importar a foto do Pinterest.")+" Se necessário, abra a foto no Pinterest, salve-a e selecione o arquivo.";return true;}};
